import{_ as e,o as t,c as o,a5 as c}from"./chunks/framework.CXvGqWf0.js";const p=JSON.parse('{"title":"漫画 · 第 14 话 Canvas：即时模式位图","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.14-canvas.md","filePath":"comics/html/EP.14-canvas.md","lastUpdated":1793421609000}'),r={name:"comics/html/EP.14-canvas.md"};function l(d,a,i,n,s,h){return t(),o("div",null,[...a[0]||(a[0]=[c('<h1 id="漫画-·-第-14-话-canvas-即时模式位图" tabindex="-1">漫画 · 第 14 话 Canvas：即时模式位图 <a class="header-anchor" href="#漫画-·-第-14-话-canvas-即时模式位图" aria-label="Permalink to &quot;漫画 · 第 14 话 Canvas：即时模式位图&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/03-canvas">docs/html/03-canvas.md</a> ｜ 原画：<a href="./EP.14-canvas.svg">EP.14-canvas.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，第一次用 canvas 画时钟，桌面浏览器好好的，一上 Retina 屏指针和数字全糊了，她以为是字体问题。</li><li><strong>标签君</strong>：HTML5 结构师，讲清 canvas 的 <code>width</code> 属性（物理像素）与 CSS 尺寸（显示尺寸）的区别，并演示 dpr 适配三步。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p><code>&lt;canvas&gt;</code> 本身只是一块画布，真正干活的是 <code>getContext(&#39;2d&#39;)</code> 返回的 2D 上下文。它是<strong>即时模式</strong>位图：每个绘制调用立刻把像素写进内存，画完即忘——浏览器不保留&quot;这里有个圆&quot;这个对象。因此动画必须由 <code>requestAnimationFrame</code> 驱动，每帧清屏、重画全部内容。本话还解决最高频的线上坑：高分屏发虚。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p><code>&lt;canvas width=&quot;300&quot; height=&quot;150&quot;&gt;</code> 定义的是<strong>绘图表面的物理像素数</strong>，CSS 宽高定义的是<strong>显示尺寸</strong>。Retina/手机的 <code>devicePixelRatio</code> 是 2 或 3，300×150 的位图被拉伸到 600×300 显示，线条和文字自然发虚。这与 CSS 矢量图形完全不同——位图一旦被放大就模糊。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>即时模式的工作循环：<code>requestAnimationFrame</code> 等屏幕刷新信号 → <code>clearRect</code> 清空位图 → 重画当前帧的全部图形，循环往复。路径本身是&quot;指令队列&quot;：<code>beginPath</code> 之后的 <code>moveTo/lineTo/arc/bezierCurveTo</code> 只是入队，直到 <code>fill()/stroke()</code> 才真正光栅化；画多个不相干图形前不调 <code>beginPath</code>，上一条路径会残留并被重复描边。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>高清适配标准三步：①<code>canvas.width/height = CSS 尺寸 × dpr</code> 放大绘图表面；②<code>canvas.style.width/height</code> 保持 CSS 尺寸不变；③<code>ctx.scale(dpr, dpr)</code> 后继续用 CSS 坐标绘制（scale 要在所有绘制前调用，<code>restore</code> 会把它一起还原）。典型场景：rAF 动画时钟、连线粒子背景、数据驱动的缓动柱状图、pointer 事件涂鸦板——图形数量大、要逐像素控制时，Canvas 比海量 DOM 省得多。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>canvas 只是画布，2d 上下文才握画笔；即时模式画完即忘，动画每帧整屏重画。</li><li>高清三步：表面 ×dpr、style 保持 CSS 尺寸、ctx.scale(dpr,dpr) 后再按 CSS 坐标绘制。</li><li>beginPath 画新图形前必调，否则旧路径残留重复描边；修改 width/height 会清空画布并重置状态。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：dpr 适配时只把 <code>canvas.width</code> 放大了 2 倍但忘了 <code>ctx.scale(2,2)</code>，画面会出现什么现象？为什么？</p><p><strong>答</strong>：所有图形都只画在画布左上角的四分之一区域，尺寸也缩小成一半。因为放大的是<strong>绘图表面</strong>（位图变成 600×300），而坐标系仍以物理像素为单位——你按设计稿画的 <code>fillRect(0,0,100,50)</code> 只落在 600×300 位图的左上角，CSS 又把整块位图缩回 300×150 显示，于是图形变小且聚在左上。<code>ctx.scale(dpr,dpr)</code> 的作用正是把坐标系整体放大，让后续绘制继续以&quot;CSS 像素&quot;为单位，浏览器光栅化时自动乘以 dpr。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>动画时钟：指针刻度自绘 + rAF 动画循环：<a href="./../../examples/html/03-canvas/index-01-clock.html">examples/html/03-canvas/index-01-clock.html</a></li><li>粒子背景：连线粒子 + 鼠标交互：<a href="./../../examples/html/03-canvas/index-02-particles.html">index-02-particles.html</a></li><li>动态柱状图：数据驱动 + 缓动动画过渡：<a href="./../../examples/html/03-canvas/index-03-barchart.html">index-03-barchart.html</a></li><li>鼠标涂鸦板：路径记录 + pointer 事件 + 清屏/撤销：<a href="./../../examples/html/03-canvas/index-04-doodle.html">index-04-doodle.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 15 话《SVG》——画完即忘的反面：图形即 DOM，无限缩放、可绑事件、还能描边生长。</p>',22)])])}const u=e(r,[["render",l]]);export{p as __pageData,u as default};
